/**
 * Direct-Postgres steward seams (Node / cy.task context).
 *
 * seedNotification / clearNotifications let specs drive a recipient's
 * notification feed deterministically WITHOUT the invite→accept→NATS chain.
 *
 * Why this exists (see the notifications flow): an INVITE_ACCEPTED notification's
 * recipient is `inviting_admin_user_id` on the `audit.identity.user_activated`
 * event — i.e. the ACTOR who drove the invite/activation. The real flow ties the
 * recipient to the INVITER's session, and the invite proxy (admin-bff) only
 * accepts a realm-admin caller — a normal org-member inviter (P2) can't invite
 * through it, and a realm admin (P1) is confined to admin-mfe. So there is no
 * live path to make a normal shell persona (P2) the recipient. This seam injects
 * the notification directly so t1-shell can assert the invite-accepted feed as P2.
 *
 * recipient_user_id MUST be the persona's Keycloak sub (== the x-user-id the feed
 * filters on == PersonaCreds.kcUserId); org_id MUST be the persona's org
 * (PersonaCreds.orgId). Inserts as the `omnicore` superuser, which bypasses RLS
 * (even FORCE RLS), so no per-tx GUC is needed. DSN overridable via
 * E2E_POSTGRES_DSN; defaults to the dev compose superuser on localhost:5432.
 */
import { Pool } from "pg";

let pool: Pool | null = null;

function getPool(): Pool {
  if (pool) return pool;
  const dsn =
    process.env.E2E_POSTGRES_DSN ??
    `postgres://omnicore:${process.env.POSTGRES_PASSWORD ?? "changeme-postgres-root"}@localhost:5432/omnicore?sslmode=disable`;
  pool = new Pool({ connectionString: dsn, max: 2 });
  return pool;
}

export type NotificationKind =
  | "invite_accepted"
  | "membership_added"
  | "workspace_switched"
  | "ingest_completed"
  | "ingest_failed"
  | "role_changed"
  | "login_new_device";

export interface SeedNotificationParams {
  /** Recipient's org (== PersonaCreds.orgId; RLS tenant key). */
  orgId: string;
  /** Recipient's Keycloak sub (== PersonaCreds.kcUserId == the feed's x-user-id). */
  recipientUserId: string;
  /** Defaults to "invite_accepted". */
  kind?: NotificationKind;
  /** Defaults to "Invite accepted". */
  title?: string;
  /** Overrides the default snippet. */
  snippet?: string;
  /** Drives the default snippet + monogram when snippet is omitted. */
  inviteeEmail?: string;
}

export interface SeedNotificationResult {
  id: string;
  recipientUserId: string;
  kind: NotificationKind;
}

function monogramOf(email: string): string {
  const c = email.trim().charAt(0).toUpperCase();
  return /[A-Z]/.test(c) ? c : "U";
}

export async function seedNotification(
  p: SeedNotificationParams,
): Promise<SeedNotificationResult> {
  const kind = p.kind ?? "invite_accepted";
  const email = p.inviteeEmail ?? "invitee@e2e.local";
  const title = p.title ?? "Invite accepted";
  const snippet = (p.snippet ?? `${email} accepted your invite`).slice(0, 140);
  const uniq = crypto.randomUUID();
  const res = await getPool().query<{ id: string }>(
    `INSERT INTO notifications.notification
       (id, org_id, recipient_user_id, kind, title, snippet, monogram, monogram_bg,
        source_event_id, nats_msg_id, created_at)
     VALUES
       (gen_random_uuid(), $1, $2, $3::notifications.notification_kind, $4, $5, $6, '#3B82F6',
        gen_random_uuid(), $7, now())
     RETURNING id`,
    [p.orgId, p.recipientUserId, kind, title, snippet, monogramOf(email), `e2e-seed-${uniq}`],
  );
  const row = res.rows[0];
  if (!row) throw new Error("seedNotification: insert returned no row");
  return { id: row.id, recipientUserId: p.recipientUserId, kind };
}

export interface ClearNotificationsParams {
  recipientUserId: string;
}

/** Delete all notifications for a recipient so a spec starts from a clean feed. */
export async function clearNotifications(
  p: ClearNotificationsParams,
): Promise<{ deleted: number }> {
  const res = await getPool().query(
    `DELETE FROM notifications.notification WHERE recipient_user_id = $1`,
    [p.recipientUserId],
  );
  return { deleted: res.rowCount ?? 0 };
}


