/**
 * Root .env loader for the Cypress e2e suite (Node / cy.task context).
 *
 * Ported from frontends/e2e/playwright.config.ts's loadRootEnv(): reads the
 * repo-root .env into process.env so the Keycloak / admin-bff task helpers can
 * read KEYCLOAK_MIGRATOR_CLIENT_SECRET etc. without the caller exporting them.
 * This mirrors the CI pattern in e2e.yml which `source`s ../../.env before the
 * e2e run.
 *
 * Two deviations from the Playwright loader, both deliberate:
 *   1. Values already present in the environment WIN (CI overrides via GitHub
 *      secrets; the local .env is only a dev fallback) — same as Playwright.
 *   2. When no `.env` exists we fall back to `.env.example`. The local dev
 *      compose stack runs on the `.env.example` `changeme-*` defaults (verified:
 *      the omnicore-migrator client authenticates with `changeme-migrator`), so
 *      the fallback lets the suite run out-of-the-box on a default dev stack
 *      with no manual `.env` copy. `.env` is always preferred when present.
 */
import fs from "node:fs";
import path from "node:path";

function parseInto(envPath: string): void {
  const content = fs.readFileSync(envPath, "utf8");
  for (const line of content.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eq = trimmed.indexOf("=");
    if (eq < 0) continue;
    const key = trimmed.slice(0, eq).trim();
    const val = trimmed.slice(eq + 1).trim();
    // Don't overwrite values already set in the environment.
    if (process.env[key] === undefined) {
      process.env[key] = val;
    }
  }
}

/**
 * Load the repo-root env file into process.env.
 *
 * @param projectDir absolute path to the cypress package dir (frontends/cypress);
 *   the repo root is two levels up. cypress.config.ts passes import.meta.dirname.
 */
export function loadRootEnv(projectDir: string): void {
  const rootDir = path.resolve(projectDir, "../..");
  // `.env` first (real secrets in CI), then `.env.example` (dev defaults).
  for (const name of [".env", ".env.example"]) {
    const candidate = path.join(rootDir, name);
    if (fs.existsSync(candidate)) {
      parseInto(candidate);
      return;
    }
  }
}

/**
 * The subset of resolved env surfaced to the browser via config.env so specs
 * can read Cypress.env('KEYCLOAK_URL') etc. No secrets are exposed here — the
 * migrator client secret and passwords stay in Node (cy.task) only.
 */
export function browserEnv(): Record<string, string> {
  return {
    KEYCLOAK_URL: process.env.KEYCLOAK_URL ?? "http://localhost:8080",
    KEYCLOAK_REALM: process.env.KEYCLOAK_REALM ?? "omnicore",
    SHELL_BFF_URL: process.env.SHELL_BFF_URL ?? "http://localhost:8082",
    ADMIN_BFF_URL: process.env.ADMIN_BFF_URL ?? "http://localhost:8084",
    // MF remote origins for the i18n pseudolocale gate's /mfes stub. Default to
    // the committed 5174/5175 (CI stack-free ports); override with I18N_ADMIN_URL
    // / I18N_FILES_URL for a local alt-port run (e.g. 6174/6175). Read here in
    // Node so they reach Cypress.env reliably (not via CYPRESS_ auto-mapping).
    I18N_ADMIN_URL: process.env.I18N_ADMIN_URL ?? "http://localhost:5174",
    I18N_FILES_URL: process.env.I18N_FILES_URL ?? "http://localhost:5175",
    // Surface CI so requireLiveStack() can fail-hard in CI but skip locally.
    CI: process.env.CI ?? "",
  };
}


