/**
 * Persona minting for the Cypress e2e suite (Node / cy.task context).
 *
 * The persona catalog lives in cypress/fixtures/personas.json (shared with the
 * browser side). This module adds the provisioning + secret logic that must not
 * ship to the browser, and exposes:
 *
 *   cy.task('mintPersona', { persona: 'P4' }) -> PersonaCreds
 *
 * mintPersona is IDEMPOTENT and uses RUN-STABLE emails (e.g. p4-member@e2e.local)
 * so cy.session can cache a persona's browser session across specs within a run.
 * On re-mint it looks the user up by email and only re-asserts the known password
 * (and org attribute), never re-creating.
 *
 * Provisioning strategy per persona kind (see fixtures/personas.json for the roster):
 *   - existing   (P1): the seed `admin` realm user; never created, creds from env.
 *   - org-owner  (P2, P8): admin-bff tenant + OWNER invite (real org membership).
 *       P8 sets `orgEnv: E2E_DEFAULT_ORG_B_ID` — when that env is set it joins the
 *       pinned "org B" as OWNER instead of minting a fresh org.
 *   - org-member (P3 ADMIN, P4 MEMBER, P5 VIEWER, P6/P7 MEMBER): admin-bff invite
 *       into the owner-persona's org at `orgRole`, plus any `realmRoles`.
 *   - stub       (P9–P12): catalog-only; not mintable via cy.login yet.
 *
 * Two authz layers, two mechanisms:
 *   - ORG-permission layer is provisioned HERE: org-root role (via invite `role`)
 *     + realm roles (via grantRealmRoles) — e.g. P6 gets range:read/range:author,
 *     P7 gets range:read.
 *   - EXERCISE-membership role (Range 3-layer authz: INSTRUCTOR / RANGE_ADMIN /
 *     STUDENT on a specific exercise) is NOT set here — it is assigned PER-SPEC by
 *     the range tranche via range-bff against a concrete exercise. Personas
 *     intentionally leave that seam open (no exercise is hardcoded). A shared
 *     helper for it, if needed, is added to support/ ON REQUEST via the steward.
 *
 * admin-bff fallback: if a real admin-bff provisioning call fails for a non-auth
 * reason (e.g. org-svc/identity-svc gRPC unavailable), mintPersona degrades to a
 * plain Keycloak-only user (orgId=null, degraded=true) so login/session journeys
 * stay green; the same code path provisions a real member once the backend is up.
 */
import {
  createOrgOwnerUser,
  createUser,
  deleteUserByEmailAndWait,
  getUserOrgId,
  grantRealmRoles,
  inviteOrgMember,
  lookupKeycloakUserIdByEmail,
  setUserEmail,
  setUserOrgId,
  setUserPassword,
} from "./keycloak.js";
import { DEFAULT_E2E_PASSWORD } from "../support/credentials";
import catalog from "../fixtures/personas.json" with { type: "json" };

/** A minted persona's usable credentials, returned to the browser via cy.task. */
export interface PersonaCreds {
  persona: string;
  email: string;
  password: string;
  /** Org id (JWT org_id claim) the persona's session resolves against, or null. */
  orgId: string | null;
  kcUserId: string;
  realmRoles: string[];
  /** True when provisioned as a plain Keycloak user because admin-bff was blocked. */
  degraded: boolean;
}

type PersonaId = keyof typeof catalog;

interface CatalogEntry {
  email: string | null;
  kind: string;
  memberOf?: string;
  realmRoles: string[];
  orgRole: string | null;
  /** Name of an env var holding a pinned org id to join (e.g. E2E_DEFAULT_ORG_B_ID
   *  for the cross-org grantee); when unset, an org-owner mints its own org. */
  orgEnv?: string;
  description: string;
}

/** Default password for all provisioned personas; overridable via env. */
function personaPassword(): string {
  // Must satisfy the realm's passwordPolicy (realm-export.json:
  // "length(12) and notUsername and passwordHistory(3)") — the Admin REST
  // reset-password endpoint enforces it, so a shorter fallback here would
  // break persona provisioning as soon as the policy lands. See
  // support/credentials.ts for the single source of truth this fallback
  // shares with the rest of the suite.
  return process.env.E2E_PERSONA_PASSWORD ?? DEFAULT_E2E_PASSWORD;
}

/** Seed `admin` realm user's password (Keycloak bootstrap user). */
function adminPassword(): string {
  return process.env.KEYCLOAK_BOOTSTRAP_USER_PASSWORD ?? "ChangeMe-Bootstrap-Pass1!";
}

function entry(persona: string): CatalogEntry {
  const e = (catalog as Record<string, CatalogEntry>)[persona];
  if (!e) {
    throw new Error(
      `mintPersona: unknown persona '${persona}'. Known: ${Object.keys(catalog).join(", ")}`,
    );
  }
  return e;
}

/**
 * Ensure a plain Keycloak user exists with the known password (idempotent).
 * Used as the admin-bff fallback and for kc-only personas.
 */
async function ensureKcUser(
  email: string,
  password: string,
  orgId?: string,
): Promise<string> {
  let id = await lookupKeycloakUserIdByEmail(email);
  if (!id) {
    id = await createUser({ email, password, passwordChangeRequired: false, orgId });
  } else {
    await setUserPassword(id, password, email);
    if (orgId) await setUserOrgId(id, orgId);
  }
  return id;
}

/**
 * Idempotency + self-heal for a persona that carries a real org membership
 * (org-owner / org-member). If a user already exists WITH an org attribute it's
 * a real prior provisioning — re-assert its password/email/roles and return
 * usable creds. If it exists WITHOUT an org attribute it's a degraded remnant
 * from an admin-bff-down run — delete it (and wait for propagation) so the
 * caller re-provisions a real membership. Returns null when there's nothing to
 * reuse (no user, or a degraded remnant was just removed).
 */
async function reuseOrHealExistingUser(
  persona: string,
  email: string,
  password: string,
  realmRoles: string[],
  degraded: boolean,
): Promise<PersonaCreds | null> {
  const existingId = await lookupKeycloakUserIdByEmail(email);
  if (!existingId) return null;
  const existingOrgId = await getUserOrgId(existingId);
  if (existingOrgId) {
    await setUserPassword(existingId, password, email);
    await setUserEmail(existingId, email);
    await grantRealmRoles(existingId, realmRoles);
    return {
      persona,
      email,
      password,
      orgId: existingOrgId,
      kcUserId: existingId,
      realmRoles,
      degraded,
    };
  }
  await deleteUserByEmailAndWait(email);
  return null;
}

export async function mintPersona(persona: string): Promise<PersonaCreds> {
  const spec = entry(persona);
  const realmRoles = spec.realmRoles ?? [];

  // ── existing: the seed `admin` realm user — never created. ──────────────────
  if (spec.kind === "existing") {
    if (!spec.email) throw new Error(`mintPersona: ${persona} has no email`);
    const kcUserId = await lookupKeycloakUserIdByEmail(spec.email);
    if (!kcUserId) {
      throw new Error(
        `mintPersona: seed user '${spec.email}' not found in Keycloak — is the realm imported?`,
      );
    }
    return {
      persona,
      email: spec.email,
      password: adminPassword(),
      orgId: await getUserOrgId(kcUserId),
      kcUserId,
      realmRoles,
      degraded: false,
    };
  }

  if (!spec.email) {
    throw new Error(
      `mintPersona: persona '${persona}' (${spec.kind}) is not mintable via Keycloak login.`,
    );
  }
  const email = spec.email;
  const password = personaPassword();

  // ── org-owner (P2): admin-bff tenant + OWNER invite; fall back to kc-only. ──
  if (spec.kind === "org-owner") {
    // Reuse an existing REAL owner (has an org attribute), or heal a degraded
    // remnant from an admin-bff-down run.
    const reused = await reuseOrHealExistingUser(
      persona,
      email,
      password,
      realmRoles,
      false,
    );
    if (reused) return reused;

    // A pinned org (orgEnv, e.g. E2E_DEFAULT_ORG_B_ID) makes this owner join an
    // EXISTING org as OWNER rather than mint a fresh one — used by P8 so the
    // cross-org grantee lives in a stable "org B". Unset → mint a fresh org.
    const pinnedOrgId = spec.orgEnv ? process.env[spec.orgEnv] : undefined;

    let kcUserId: string;
    let orgId: string | null;
    let degraded = false;
    try {
      if (pinnedOrgId) {
        kcUserId = await inviteOrgMember({
          email,
          password,
          orgId: pinnedOrgId,
          role: "OWNER",
        });
        await setUserOrgId(kcUserId, pinnedOrgId);
        orgId = pinnedOrgId;
      } else {
        const r = await createOrgOwnerUser({
          email,
          password,
          orgSlug: `e2e-${persona.toLowerCase()}-org-${Date.now()}`,
          orgName: `E2E ${persona} Org`,
        });
        kcUserId = r.keycloakUserId;
        orgId = r.orgId;
      }
    } catch {
      // Intentionally does NOT log the caught error: its message can carry
      // request/response data from the provisioning helpers we hand the
      // env-sourced password to, and clear-text-logging that is a security
      // smell (CodeQL js/clear-text-logging). The authoritative failure cause
      // is available server-side in admin-bff's logs/traces. We keep only the
      // non-sensitive signal: which persona degraded and which path failed.
      console.warn(
        `[personas] ${persona} org-owner provisioning via admin-bff failed; ` +
          `falling back to a Keycloak-only user (no server-side org membership). ` +
          `See admin-bff logs/traces for the failure cause.`,
      );
      kcUserId = await ensureKcUser(email, password);
      orgId = null;
      degraded = true;
    }
    await setUserEmail(kcUserId, email);
    await grantRealmRoles(kcUserId, realmRoles);
    return { persona, email, password, orgId, kcUserId, realmRoles, degraded };
  }

  // ── org-member (P4): admin-bff invite into the owner persona's org. ─────────
  if (spec.kind === "org-member") {
    const ownerId = spec.memberOf ?? "P2";
    const owner = await mintPersona(ownerId);

    // Reuse an existing REAL member (has an org attribute), or heal a degraded
    // remnant so we re-provision a real membership. Inherits the owner's
    // degraded flag when a real member is reused.
    const reused = await reuseOrHealExistingUser(
      persona,
      email,
      password,
      realmRoles,
      owner.degraded,
    );
    if (reused) return reused;

    let kcUserId: string;
    let orgId: string | null;
    let degraded = owner.degraded;
    if (owner.orgId) {
      try {
        kcUserId = await inviteOrgMember({
          email,
          password,
          orgId: owner.orgId,
          role: (spec.orgRole as InviteRole | null) ?? "MEMBER",
        });
        await setUserOrgId(kcUserId, owner.orgId);
        orgId = owner.orgId;
      } catch {
        // See the org-owner branch above: the caught error is deliberately not
        // logged (it can carry secret-derived request/response data — CodeQL
        // js/clear-text-logging). The failure cause lives in admin-bff's
        // logs/traces; we log only the non-sensitive persona + path signal.
        console.warn(
          `[personas] ${persona} org-member provisioning via admin-bff failed; ` +
            `falling back to a Keycloak-only user. ` +
            `See admin-bff logs/traces for the failure cause.`,
        );
        kcUserId = await ensureKcUser(email, password, owner.orgId);
        orgId = owner.orgId;
        degraded = true;
      }
    } else {
      // Owner had no real org (admin-bff blocked) — mint a bare KC user.
      kcUserId = await ensureKcUser(email, password);
      orgId = null;
      degraded = true;
    }
    await setUserEmail(kcUserId, email);
    await grantRealmRoles(kcUserId, realmRoles);
    return { persona, email, password, orgId, kcUserId, realmRoles, degraded };
  }

  throw new Error(
    `mintPersona: persona '${persona}' has kind '${spec.kind}' which is not yet ` +
      `implemented (stub). Wire it in a later tranche.`,
  );
}

type InviteRole = "MEMBER" | "ADMIN" | "OWNER" | "VIEWER";

// Re-export the persona id list for typing convenience.
export type { PersonaId };



