/**
 * cy.task handler registration (Node process). Wired into cypress.config.ts's
 * setupNodeEvents. Keeps all Keycloak/admin-bff secrets server-side.
 *
 * Handlers must return a value or a Promise (Cypress forbids `undefined`), so
 * the void-returning Keycloak helpers resolve to `null`.
 */
import type Cypress from "cypress";
import {
  createUser,
  grantRealmRoles,
  lookupKeycloakUserIdByEmail,
  setUserOrgId,
  setUserPassword,
  type CreateUserOptions,
} from "./keycloak.js";
import { mintPersona } from "./personas.js";
import {
  clearNotifications,
  seedNotification,
  type ClearNotificationsParams,
  type SeedNotificationParams,
} from "./db.js";
import {
  participantLogin,
  seedXParticipant,
  type ParticipantLoginParams,
  type SeedXParticipantParams,
} from "./participant.js";

export function registerTasks(on: Cypress.PluginEvents): void {
  on("task", {
    /** Idempotently mint a persona and return usable browser credentials. */
    mintPersona: (arg: { persona: string }) => mintPersona(arg.persona),

    /** Create a Keycloak user (used by cy.loginFresh). Returns the user id. */
    kcCreateUser: (opts: CreateUserOptions) => createUser(opts),

    /** Look up a Keycloak user id by email. Returns the id or null. */
    kcLookupUserId: (arg: { email: string }) =>
      lookupKeycloakUserIdByEmail(arg.email),

    kcSetUserPassword: async (arg: { keycloakUserId: string; password: string }) => {
      await setUserPassword(arg.keycloakUserId, arg.password);
      return null;
    },

    kcSetUserOrgId: async (arg: { keycloakUserId: string; orgId: string }) => {
      await setUserOrgId(arg.keycloakUserId, arg.orgId);
      return null;
    },

    kcGrantRealmRoles: async (arg: {
      keycloakUserId: string;
      roles: readonly string[];
    }) => {
      await grantRealmRoles(arg.keycloakUserId, arg.roles);
      return null;
    },

    /** Inject a notification into a recipient's feed (steward seam). */
    seedNotification: (arg: SeedNotificationParams) => seedNotification(arg),

    /** Clear a recipient's notification feed for a deterministic start. */
    clearNotifications: (arg: ClearNotificationsParams) => clearNotifications(arg),

    /** Provision an exercise + synthetic character + participant credential. */
    seedXParticipant: (arg: SeedXParticipantParams) => seedXParticipant(arg),

    /** Log a participant credential into the Kite or Commons surface; returns the cookie. */
    participantLogin: (arg: ParticipantLoginParams) => participantLogin(arg),
  });
}


--- frontends/cypress/cypress/tasks/keycloak.ts (663 lines) ---
/**
 * Keycloak admin-REST + admin-bff helpers for the Cypress e2e suite.
 *
 * Ported from frontends/e2e/tests/helpers/keycloak.ts. These run in the Node
 * (cy.task) process, never in the browser — the omnicore-migrator client secret
 * stays server-side.
 *
 * Authentication: mints the omnicore-migrator service-account token via the
 * client_credentials grant (KEYCLOAK_MIGRATOR_CLIENT_SECRET). That token holds
 * realm-management `manage-users` + the realm `admin` role, which is enough for
 * the Keycloak admin-REST helpers below (createUser, setUserPassword,
 * grantRealmRole(s), setUserOrgId, lookups). It deliberately does NOT hold
 * `view-realm`, so every helper here must stay on user-scoped admin endpoints --
 * realm-wide reads such as `GET /admin/realms/{realm}/roles/{name}` return 403.
 *
 * Two tokens, two audiences:
 *   - Keycloak admin-REST helpers use the omnicore-migrator client_credentials
 *     token (getAdminToken) — it carries the realm-management aud.
 *   - admin-bff helpers (createOrgOwnerUser / inviteOrgMember) use the
 *     omnicore-seed ROPC token (getSeedToken) — admin-bff validates aud=admin-bff,
 *     which the migrator token deliberately lacks. omnicore-seed is a dev-only
 *     password client with the admin-bff audience mapper + fullScopeAllowed;
 *     logging in the seed `admin` realm user yields aud=admin-bff + the `admin`
 *     realm role, passing admin-bff's AuthRequired + platform-admin gates.
 *
 * mintPersona still falls back to Keycloak-only provisioning if an admin-bff call
 * fails for a NON-auth reason (e.g. org-svc/identity-svc gRPC unavailable), so
 * login journeys stay green while those services are unhealthy.
 */

function keycloakUrl(): string {
  return process.env.KEYCLOAK_URL ?? "http://localhost:8080";
}

function realm(): string {
  return process.env.KEYCLOAK_REALM ?? "omnicore";
}

function migratorClientId(): string {
  return process.env.KEYCLOAK_MIGRATOR_CLIENT_ID ?? "omnicore-migrator";
}

function adminBffUrl(): string {
  return process.env.ADMIN_BFF_URL ?? "http://localhost:8084";
}

function seedClientId(): string {
  return process.env.OIDC_SEED_CLIENT_ID ?? "omnicore-seed";
}

function seedClientSecret(): string {
  const secret = process.env.OIDC_SEED_CLIENT_SECRET;
  if (!secret) {
    throw new Error(
      "OIDC_SEED_CLIENT_SECRET is not set. This client's secret must not " +
        "default to a hardcoded value — set it in .env (see .env.example).",
    );
  }
  return secret;
}

function seedAdminUsername(): string {
  return process.env.KEYCLOAK_BOOTSTRAP_USERNAME ?? "admin";
}

function seedAdminPassword(): string {
  return (
    process.env.KEYCLOAK_BOOTSTRAP_USER_PASSWORD ?? "ChangeMe-Bootstrap-Pass1!"
  );
}

// ---------------------------------------------------------------------------
// Token acquisition
// ---------------------------------------------------------------------------

let cachedToken: { value: string; expiresAt: number } | null = null;

/**
 * Return the omnicore-migrator service-account access token. Mints fresh on the
 * first call and caches until 30s before expiry, re-minting on cache miss.
 * Reads the client secret from KEYCLOAK_MIGRATOR_CLIENT_SECRET — fails closed.
 */
export async function getAdminToken(): Promise<string> {
  if (cachedToken && Date.now() < cachedToken.expiresAt - 30_000) {
    return cachedToken.value;
  }
  const secret = process.env.KEYCLOAK_MIGRATOR_CLIENT_SECRET;
  if (!secret) {
    throw new Error(
      "KEYCLOAK_MIGRATOR_CLIENT_SECRET is not set. The e2e helper mints the " +
        "migrator service-account token via client_credentials grant; the " +
        "client secret must be sourced from .env (or .env.example) before running tests.",
    );
  }
  const r = await fetch(
    `${keycloakUrl()}/realms/${realm()}/protocol/openid-connect/token`,
    {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({
        grant_type: "client_credentials",
        client_id: migratorClientId(),
        client_secret: secret,
      }),
    },
  );
  if (!r.ok) {
    throw new Error(`token mint failed: ${r.status} ${await r.text()}`);
  }
  const body = (await r.json()) as { access_token: string; expires_in: number };
  cachedToken = {
    value: body.access_token,
    expiresAt: Date.now() + body.expires_in * 1000,
  };
  return cachedToken.value;
}

let cachedSeedToken: { value: string; expiresAt: number } | null = null;

/**
 * Return an omnicore-seed access token (dev ROPC client) for admin-bff calls.
 *
 * The omnicore-migrator token deliberately lacks admin-bff in its aud, so
 * admin-bff 403s it. The omnicore-seed client (realm-export.json) is a dev-only
 * password/ROPC client with the admin-bff audience mapper + fullScopeAllowed;
 * logging in the seed `admin` realm user through it yields aud=admin-bff and the
 * `admin` realm role, which passes admin-bff's AuthRequired + platform-admin
 * gates. Used ONLY for admin-bff-targeting helpers; the Keycloak admin-REST
 * calls keep using the migrator token (realm-management aud).
 */
export async function getSeedToken(): Promise<string> {
  if (cachedSeedToken && Date.now() < cachedSeedToken.expiresAt - 30_000) {
    return cachedSeedToken.value;
  }
  const token = await ropcToken(seedAdminUsername(), seedAdminPassword());
  // Cache with a conservative 4-min TTL (seed tokens are short-lived).
  cachedSeedToken = { value: token, expiresAt: Date.now() + 240_000 };
  return cachedSeedToken.value;
}

/**
 * Mint an access token for ANY realm user via the omnicore-seed ROPC (password)
 * client. The seed client's aud includes admin-bff / org-svc / range-bff /
 * identity-svc / range-svc + fullScopeAllowed, so the resulting token can call
 * those workspace BFFs AS the given user (subject to that user's own roles +
 * memberships). Used to obtain an instructor (e.g. P6) bearer for the range-bff
 * participant-credential flow. Uncached — callers mint per use.
 */
export async function ropcToken(
  username: string,
  password: string,
): Promise<string> {
  const r = await fetch(
    `${keycloakUrl()}/realms/${realm()}/protocol/openid-connect/token`,
    {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({
        grant_type: "password",
        client_id: seedClientId(),
        client_secret: seedClientSecret(),
        username,
        password,
        scope: "openid",
      }),
    },
  );
  if (!r.ok) {
    throw new Error(`ropcToken(${username}) failed: ${r.status} ${await r.text()}`);
  }
  const body = (await r.json()) as { access_token: string };
  return body.access_token;
}

// ---------------------------------------------------------------------------
// User management (Keycloak admin REST — migrator token, realm-management aud)
// ---------------------------------------------------------------------------

export interface CreateUserOptions {
  email: string;
  password: string;
  passwordChangeRequired?: boolean;
  /** Optional omnicore_org_id user attribute (drives the `org_id` JWT claim). */
  orgId?: string;
}

/**
 * Create a Keycloak user via POST /admin/realms/{realm}/users.
 * @returns the userId parsed from the Location header.
 */
export async function createUser(opts: CreateUserOptions): Promise<string> {
  const token = await getAdminToken();
  const requiredActions = opts.passwordChangeRequired ? ["UPDATE_PASSWORD"] : [];
  const r = await fetch(`${keycloakUrl()}/admin/realms/${realm()}/users`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      username: opts.email,
      email: opts.email,
      firstName: "Test",
      lastName: "User",
      enabled: true,
      emailVerified: true,
      credentials: [
        {
          type: "password",
          value: opts.password,
          temporary: opts.passwordChangeRequired ?? false,
        },
      ],
      requiredActions,
      ...(opts.orgId ? { attributes: { omnicore_org_id: [opts.orgId] } } : {}),
    }),
  });
  if (!r.ok) {
    throw new Error(`createUser failed: ${r.status} ${await r.text()}`);
  }
  const location = r.headers.get("Location");
  if (!location) {
    throw new Error("createUser: 201 but no Location header");
  }
  const userId = location.split("/").pop();
  if (!userId) {
    throw new Error(`createUser: could not parse userId from ${location}`);
  }
  return userId;
}

/**
 * Look up a Keycloak user's internal id by email. Returns null when absent.
 *
 * Queries by USERNAME, not the `email` field. The platform invariant is
 * username == email for every provisioned user, and — critically —
 * identity-svc.Invite creates Keycloak users with the username set but the
 * `email` FIELD LEFT NULL. A `?email=` query therefore misses every
 * invite-created user (org owners/members), which previously made re-mint
 * conflict on the username and trip identity-svc's phantom-user guard. A
 * `?username=` exact query matches both invite-created (email null) and
 * directly-created (email set) users.
 */
export async function lookupKeycloakUserIdByEmail(
  email: string,
): Promise<string | null> {
  const token = await getAdminToken();
  const r = await fetch(
    `${keycloakUrl()}/admin/realms/${realm()}/users?username=${encodeURIComponent(email)}&exact=true`,
    { headers: { Authorization: `Bearer ${token}` } },
  );
  if (!r.ok) {
    throw new Error(
      `lookupKeycloakUserIdByEmail: query failed: ${r.status} ${await r.text()}`,
    );
  }
  const users = (await r.json()) as Array<{ id: string }>;
  return users.length > 0 ? (users[0]?.id ?? null) : null;
}

/**
 * Look up a Keycloak user's current omnicore_org_id attribute (the value that
 * drives the JWT `org_id` claim). Returns null when the attribute is unset.
 * Used by mintPersona to recover a previously-minted persona's org id on
 * re-mint (idempotency) without re-provisioning.
 */
export async function getUserOrgId(
  keycloakUserId: string,
): Promise<string | null> {
  const token = await getAdminToken();
  const r = await fetch(
    `${keycloakUrl()}/admin/realms/${realm()}/users/${keycloakUserId}`,
    { headers: { Authorization: `Bearer ${token}` } },
  );
  if (!r.ok) {
    throw new Error(`getUserOrgId: GET failed: ${r.status} ${await r.text()}`);
  }
  const user = (await r.json()) as {
    attributes?: { omnicore_org_id?: string[] };
  };
  return user.attributes?.omnicore_org_id?.[0] ?? null;
}

/**
 * Delete a Keycloak user by internal id (idempotent — 404 is treated as success).
 */
export async function deleteUser(keycloakUserId: string): Promise<void> {
  const token = await getAdminToken();
  const r = await fetch(
    `${keycloakUrl()}/admin/realms/${realm()}/users/${keycloakUserId}`,
    { method: "DELETE", headers: { Authorization: `Bearer ${token}` } },
  );
  if (!r.ok && r.status !== 404) {
    throw new Error(`deleteUser: DELETE failed: ${r.status} ${await r.text()}`);
  }
}

/**
 * Delete a Keycloak user by email and WAIT until the deletion has propagated
 * (lookup returns null). Used by mintPersona to self-heal a degraded persona
 * remnant — a KC-only user left behind from a run where admin-bff was
 * unreachable. Such a user is "poison": identity-svc.Invite refuses to invite
 * over a pre-existing IdP user whose email its own store doesn't know
 * ("refusing to insert a phantom user"), so the only heal is to remove the KC
 * user and re-provision cleanly. Deleting without waiting races Keycloak's
 * eventual consistency and re-triggers the same phantom guard, hence the poll.
 */
export async function deleteUserByEmailAndWait(email: string): Promise<void> {
  const id = await lookupKeycloakUserIdByEmail(email);
  if (!id) return;
  await deleteUser(id);
  for (let i = 0; i < 20; i++) {
    if ((await lookupKeycloakUserIdByEmail(email)) === null) return;
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error(
    `deleteUserByEmailAndWait: ${email} still present after delete + 10s wait`,
  );
}

/**
 * PUT a partial representation to a Keycloak user (PUT /admin/realms/{realm}/
 * users/{id}). Keycloak merges the patch, so callers pass only the fields they
 * change. `label` prefixes the thrown error so failures stay attributable.
 */
async function updateUser(
  keycloakUserId: string,
  patch: object,
  label: string,
): Promise<void> {
  const token = await getAdminToken();
  const r = await fetch(
    `${keycloakUrl()}/admin/realms/${realm()}/users/${keycloakUserId}`,
    {
      method: "PUT",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(patch),
    },
  );
  if (!r.ok) {
    throw new Error(`${label}: PUT failed: ${r.status} ${await r.text()}`);
  }
}

/**
 * Probe whether `password` already authenticates as `username`, via the
 * omnicore-seed ROPC client. Used to keep persona re-mint idempotent under
 * the realm's passwordHistory(3) policy: Keycloak's Admin REST reset-password
 * endpoint rejects reusing a password already in a user's credential
 * history, so a caller that re-asserts the SAME password on every run (e.g.
 * personas.ts) would otherwise fail on the second and every later run.
 * Returns false (never throws) on ANY failure — wrong password, a pending
 * required action, missing secret, network error — so callers only treat a
 * `true` result as "safe to skip the reset"; a `false` always falls through
 * to the normal reset-password call.
 */
export async function passwordAlreadyValid(
  username: string,
  password: string,
): Promise<boolean> {
  try {
    const r = await fetch(
      `${keycloakUrl()}/realms/${realm()}/protocol/openid-connect/token`,
      {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
          grant_type: "password",
          client_id: seedClientId(),
          client_secret: seedClientSecret(),
          username,
          password,
          scope: "openid",
        }),
      },
    );
    return r.ok;
  } catch {
    return false;
  }
}

/**
 * Set (permanent) a Keycloak user's password and clear UPDATE_PASSWORD so the
 * user can log in without the force-change-password flow. Idempotent.
 *
 * When `username` is supplied, first probes whether `password` already
 * authenticates (see passwordAlreadyValid) and skips the reset entirely if
 * so — required under the realm's passwordHistory(3) policy, which would
 * otherwise reject re-asserting the same password on every idempotent
 * re-mint. Omit `username` for one-shot password sets on a brand-new user,
 * where there is nothing to reuse and no probe is needed.
 */
export async function setUserPassword(
  keycloakUserId: string,
  password: string,
  username?: string,
): Promise<void> {
  if (username && (await passwordAlreadyValid(username, password))) {
    return;
  }

  const token = await getAdminToken();

  const credR = await fetch(
    `${keycloakUrl()}/admin/realms/${realm()}/users/${keycloakUserId}/reset-password`,
    {
      method: "PUT",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ type: "password", value: password, temporary: false }),
    },
  );
  if (!credR.ok) {
    throw new Error(
      `setUserPassword: reset-password failed: ${credR.status} ${await credR.text()}`,
    );
  }

  await updateUser(
    keycloakUserId,
    { requiredActions: [] },
    "setUserPassword: clear requiredActions",
  );
}

/**
 * Grant a single realm role to an existing Keycloak user.
 */
export async function grantRealmRole(
  keycloakUserId: string,
  role: string,
): Promise<void> {
  await grantRealmRoles(keycloakUserId, [role]);
}

/**
 * Grant one or more realm roles to an existing Keycloak user.
 *
 * Role ids are resolved from the USER-scoped role-mapping endpoints, not from
 * the realm-wide `GET /roles/{name}`. The migrator service-account holds only
 * realm-management `manage-users` (narrowed from `realm-admin` in #2379), and
 * `manage-users` does not carry `view-realm` — so the realm-wide lookup 403s
 * while `users/{id}/role-mappings/realm{,/available}` and the grant itself are
 * all permitted. Merging `available` with the roles already mapped keeps this
 * idempotent: an already-granted role drops out of `available`, and re-running
 * mintPersona against an existing user must not fail on it.
 */
export async function grantRealmRoles(
  keycloakUserId: string,
  roles: readonly string[],
): Promise<void> {
  if (roles.length === 0) return;
  const token = await getAdminToken();

  const base = `${keycloakUrl()}/admin/realms/${realm()}/users/${keycloakUserId}/role-mappings/realm`;
  const byName = new Map<string, { id: string; name: string }>();
  const granted = new Set<string>();

  for (const [url, isGranted] of [
    [`${base}/available`, false],
    [base, true],
  ] as const) {
    const r = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
    if (!r.ok) {
      throw new Error(
        `grantRealmRoles: list ${url.endsWith("/available") ? "available" : "granted"} roles failed: ${r.status} ${await r.text()}`,
      );
    }
    for (const rep of (await r.json()) as Array<{ id: string; name: string }>) {
      byName.set(rep.name, { id: rep.id, name: rep.name });
      if (isGranted) granted.add(rep.name);
    }
  }

  const reps: Array<{ id: string; name: string }> = [];
  for (const role of roles) {
    const rep = byName.get(role);
    if (!rep) {
      throw new Error(
        `grantRealmRoles: realm role '${role}' does not exist in realm '${realm()}' ` +
          `(not among this user's granted or available realm roles)`,
      );
    }
    if (!granted.has(role)) reps.push(rep);
  }
  if (reps.length === 0) return;

  const grantR = await fetch(
    `${keycloakUrl()}/admin/realms/${realm()}/users/${keycloakUserId}/role-mappings/realm`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(reps),
    },
  );
  if (!grantR.ok) {
    throw new Error(
      `grantRealmRoles: grant [${roles.join(", ")}] failed: ${grantR.status} ${await grantR.text()}`,
    );
  }
}

/**
 * Ensure a Keycloak user's `email` field is set (and verified). Idempotent.
 *
 * identity-svc.Invite creates users with the username set but the `email` FIELD
 * left NULL, so their JWT `email` claim is empty and the shell's user menu (which
 * renders `session.email`) shows nothing. Populating the email field gives the
 * persona a complete, realistic profile and a populated email claim.
 */
export async function setUserEmail(
  keycloakUserId: string,
  email: string,
): Promise<void> {
  await updateUser(keycloakUserId, { email, emailVerified: true }, "setUserEmail");
}

/**
 * Set (or replace) a Keycloak user's omnicore_org_id attribute — the realm
 * protocol mapper maps this to the JWT `org_id` claim, which shell-bff /session
 * resolves the caller's ORG role + capabilities against. The user must re-login
 * for a new attribute to flow into a fresh access token.
 */
export async function setUserOrgId(
  keycloakUserId: string,
  orgId: string,
): Promise<void> {
  await updateUser(
    keycloakUserId,
    { attributes: { omnicore_org_id: [orgId] } },
    "setUserOrgId",
  );
}

// ---------------------------------------------------------------------------
// Org provisioning via admin-bff (see NOTE in the file header re: aud=admin-bff)
// ---------------------------------------------------------------------------

export interface CreateOrgOwnerUserOptions {
  email: string;
  password: string;
  /** Unique slug for the new org (unique per run to avoid UNIQUE conflicts). */
  orgSlug: string;
  orgName: string;
}

export interface CreateOrgOwnerUserResult {
  keycloakUserId: string;
  /** The org id the user was invited into (and holds OWNER membership at). */
  orgId: string;
}

/**
 * Create a non-realm-admin user holding an org-root OWNER membership, by driving
 * admin-bff (tenant create + org-only OWNER invite) with the migrator token.
 * See the file header NOTE — currently blocked by admin-bff's aud check.
 */
export async function createOrgOwnerUser(
  opts: CreateOrgOwnerUserOptions,
): Promise<CreateOrgOwnerUserResult> {
  const { email, password, orgSlug, orgName } = opts;
  // admin-bff calls require aud=admin-bff -> use the seed ROPC token, NOT the
  // migrator token. The KC admin-REST calls below (lookup/setPassword/setOrgId)
  // use the migrator token internally (realm-management aud).
  const seedToken = await getSeedToken();

  const orgR = await fetch(`${adminBffUrl()}/api/v1/admin/tenants`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${seedToken}`,
      "Content-Type": "application/json",
      "Idempotency-Key": crypto.randomUUID(),
    },
    body: JSON.stringify({ name: orgName, slug: orgSlug }),
  });
  if (!orgR.ok) {
    throw new Error(
      `createOrgOwnerUser: org create failed: ${orgR.status} ${await orgR.text()}`,
    );
  }
  const orgBody = (await orgR.json()) as {
    data?: { tenant?: { id: string } };
  };
  const orgId = orgBody.data?.tenant?.id;
  if (!orgId) {
    throw new Error(
      "createOrgOwnerUser: could not parse org id from tenant-create response",
    );
  }

  // Invite the OWNER into the freshly-created org (invite POST + lookup +
  // password) via the shared org-invite helper, then pin the org attribute.
  const keycloakUserId = await inviteOrgMember({
    email,
    password,
    orgId,
    role: "OWNER",
  });
  await setUserOrgId(keycloakUserId, orgId);

  return { keycloakUserId, orgId };
}

export interface InviteOrgMemberOptions {
  email: string;
  password: string;
  /** The EXISTING org root to invite into. */
  orgId: string;
  role?: "MEMBER" | "ADMIN" | "OWNER" | "VIEWER";
}

/**
 * Invite an additional user into an already-existing org via admin-bff's
 * org-only invite route. See the file header NOTE re: aud=admin-bff.
 * @returns the invitee's Keycloak user id.
 */
export async function inviteOrgMember(
  opts: InviteOrgMemberOptions,
): Promise<string> {
  const { email, password, orgId, role = "MEMBER" } = opts;
  // admin-bff requires aud=admin-bff -> seed ROPC token (not the migrator token).
  const seedToken = await getSeedToken();

  const inviteR = await fetch(`${adminBffUrl()}/api/v1/admin/users/invite`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${seedToken}`,
      "Content-Type": "application/json",
      "Idempotency-Key": crypto.randomUUID(),
    },
    body: JSON.stringify({
      email,
      display_name: email.split("@")[0],
      org_id: orgId,
      role,
    }),
  });
  if (!inviteR.ok) {
    throw new Error(
      `inviteOrgMember: invite failed: ${inviteR.status} ${await inviteR.text()}`,
    );
  }

  const keycloakUserId = await lookupKeycloakUserIdByEmail(email);
  if (!keycloakUserId) {
    throw new Error(
      `inviteOrgMember: Keycloak user not found for ${email} after invite.`,
    );
  }
  await setUserPassword(keycloakUserId, password);

  return keycloakUserId;
}


