/**
 * Participant-surface seams for P9 (Kite) and P10 (Commons) — the standalone
 * participant clones served OUTSIDE the Keycloak shell (Epic #262 / #267).
 *
 * These participants authenticate with a per-character CREDENTIAL (handle +
 * password), NOT a Keycloak session. The credential is minted by an INSTRUCTOR
 * (a range:author org member with RANGE_ADMIN on the exercise — the exercise
 * CREATOR gets that automatically). A realm admin (P1/seed) CANNOT be the
 * instructor: range-bff 403s realm-admin tokens ("platform administrators cannot
 * access workspace resources", invariant 8). So the instructor is P6 by default
 * (range instructor persona), whose token is minted via the omnicore-seed ROPC
 * client (its aud includes range-bff).
 *
 * Full chain (all proven live):
 *   1. ensure the instructor persona exists (mintPersona)
 *   2. instructor ROPC token (aud=range-bff)
 *   3. POST /api/v1/range/exercises/                → exercise (draft)
 *   4. POST /api/v1/range/exercises/{id}/characters → synthetic character
 *   5. POST /api/v1/kite/exercises/{id}/credentials:generate {character_id} → {handle, password}
 *   6. POST /api/v1/kite/login  OR  /api/v1/commons/login {exercise_id, handle, password}
 *      → Set-Cookie kite_session (Path=/api/v1/kite) / commons_session (Path=/api/v1/commons)
 *
 * The SAME credential authenticates BOTH the Kite and Commons surfaces. The
 * cy.loginParticipantX / cy.loginParticipantCommons commands (support/commands.ts)
 * plant the returned cookie so the spec can drive the participant surface.
 */
import { mintPersona } from "./personas.js";
import { ropcToken } from "./keycloak.js";

function rangeBffUrl(): string {
  return process.env.RANGE_BFF_URL ?? "http://localhost:8087";
}

interface Envelope<T> {
  data: T | null;
  error?: { code: string; message: string };
}

async function postJson<T>(
  path: string,
  token: string | null,
  body: unknown,
): Promise<T> {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    "Idempotency-Key": crypto.randomUUID(),
  };
  if (token) headers.Authorization = `Bearer ${token}`;
  const r = await fetch(`${rangeBffUrl()}${path}`, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
  });
  const text = await r.text();
  if (!r.ok) throw new Error(`POST ${path} -> ${r.status} ${text}`);
  const env = JSON.parse(text) as Envelope<T>;
  if (env.data === null || env.data === undefined) {
    throw new Error(`POST ${path}: empty data (${text})`);
  }
  return env.data;
}

export interface SeedXParticipantParams {
  /** Instructor persona (default "P6" — range:author org member). */
  instructorPersona?: string;
  exerciseName?: string;
  /** Character username (also the default Kite/Commons handle). */
  username?: string;
  displayName?: string;
}

export interface SeedXParticipantResult {
  exerciseId: string;
  characterId: string;
  handle: string;
  password: string;
  orgId: string | null;
}

/** Provision an exercise + synthetic character + participant credential. */
export async function seedXParticipant(
  p: SeedXParticipantParams = {},
): Promise<SeedXParticipantResult> {
  const instructor = await mintPersona(p.instructorPersona ?? "P6");
  const token = await ropcToken(instructor.email, instructor.password);
  const uniq = Date.now().toString(36);
  const username = p.username ?? `e2ex_${uniq}`;

  const ex = await postJson<{ exercise: { id: string } }>(
    "/api/v1/range/exercises/",
    token,
    {
      name: p.exerciseName ?? `E2E Participant ${uniq}`,
      description: "e2e participant seam",
      scenario: "e2e",
    },
  );
  const exerciseId = ex.exercise.id;

  const ch = await postJson<{ character: { id: string } }>(
    `/api/v1/range/exercises/${exerciseId}/characters`,
    token,
    {
      username,
      display_name: p.displayName ?? username,
      bio: "e2e participant",
      is_synthetic: true,
    },
  );
  const characterId = ch.character.id;

  const cred = await postJson<{ handle: string; password: string }>(
    `/api/v1/kite/exercises/${exerciseId}/credentials:generate`,
    token,
    { character_id: characterId },
  );

  return {
    exerciseId,
    characterId,
    handle: cred.handle,
    password: cred.password,
    orgId: instructor.orgId,
  };
}

export interface ParticipantLoginParams {
  surface: "kite" | "commons";
  exerciseId: string;
  handle: string;
  password: string;
}

export interface ParticipantCookie {
  /** "kite_session" or "commons_session". */
  name: string;
  value: string;
  /** Cookie Path attribute ("/api/v1/kite" or "/api/v1/commons"). */
  path: string;
}

/**
 * Authenticate a participant credential against the Kite or Commons login
 * endpoint and return the opaque session cookie. The caller (cy command)
 * plants it.
 */
export async function participantLogin(
  p: ParticipantLoginParams,
): Promise<ParticipantCookie> {
  const cookieName = p.surface === "kite" ? "kite_session" : "commons_session";
  const r = await fetch(`${rangeBffUrl()}/api/v1/${p.surface}/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      exercise_id: p.exerciseId,
      handle: p.handle,
      password: p.password,
    }),
  });
  if (!r.ok) {
    throw new Error(`${p.surface}/login -> ${r.status} ${await r.text()}`);
  }
  const setCookies = r.headers.getSetCookie();
  const line = setCookies.find((c) => c.startsWith(`${cookieName}=`));
  if (!line) {
    throw new Error(`${p.surface}/login: no ${cookieName} in Set-Cookie`);
  }
  const value = line.slice(cookieName.length + 1).split(";")[0] ?? "";
  return { name: cookieName, value, path: `/api/v1/${p.surface}` };
}


